        t=x[0]
        if t=="col": return x[1]
        if t=="lit":
            v=x[1]; return "NULL" if v is None else ("TRUE" if v is True else "FALSE" if v is False else repr(v) if isinstance(v,str) else str(v))
        if t=="call":return x[1]+"("+("*" if x[2]==[("star",)] else ", ".join(f(a) for a in x[2]))+")"
        if t=="un":return x[1]+" "+f(x[2]) if x[1]=="NOT" else "-"+f(x[2])
        if t=="bin":return f(x[2])+" "+x[1]+" "+f(x[3])
        if t=="isnull":return f(x[1])+" IS "+("NOT " if x[2] else "")+"NULL"
        if t=="in":return f(x[1])+" "+("NOT " if x[3] else "")+"IN ("+", ".join(f(a) for a in x[2])+")"
        if t=="like":return f(x[1])+" LIKE "+f(x[2])
        if t=="between":return f(x[1])+" BETWEEN "+f(x[2])+" AND "+f(x[3])
        return "*"
    return f(e)

